import { Controller, Get, Post, Put, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function numberOf(value: unknown, label: string): number {
  if (value === null || value === undefined || value === '' || typeof value === 'boolean') {
    throw invalid(label + ' 값을 입력하세요.');
  }
  const n = Number(value);
  if (!Number.isFinite(n)) {
    throw invalid(label + ' 값은 숫자여야 합니다.');
  }
  return n;
}

function parseGrade(data: Record<string, unknown>) {
  const gradeGroup = typeof data['gradeGroup'] === 'string' ? data['gradeGroup'].trim() : '';
  if (gradeGroup === '' || gradeGroup.length > 100) {
    throw invalid('직급/직군은 1~100자로 입력하세요.');
  }
  const step = numberOf(data['step'], '호봉');
  if (!Number.isInteger(step) || step <= 0) {
    throw invalid('호봉은 1 이상의 정수여야 합니다.');
  }
  const amount = numberOf(data['amount'], '호봉별 금액');
  if (amount < 0) {
    throw invalid('호봉별 금액은 0 이상이어야 합니다.');
  }
  let effectiveFrom: string | null = null;
  const raw = data['effectiveFrom'];
  if (raw !== null && raw !== undefined && raw !== '') {
    if (typeof raw !== 'string' || !DATE_PATTERN.test(raw)) {
      throw invalid('적용 시작일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    effectiveFrom = raw;
  }
  return { gradeGroup, step, amount, effectiveFrom };
}

@Controller('api/v1')
export class FnSfr02107Controller {
  @Post('/salary-grade-tables')
  @HttpCode(200)
  async createSalaryGradeTable(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const input = parseGrade(data);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE grade_group = :gradeGroup AND step = CAST(:step AS integer)',
        { gradeGroup: input.gradeGroup, step: input.step },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SALARY_GRADE_DUPLICATED', '동일 직급/직군에 같은 호봉이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO salary_grade_table (grade_group, step, amount, effective_from, created_at, updated_at) ' +
          'VALUES (:gradeGroup, CAST(:step AS integer), CAST(:amount AS numeric), CAST(:effectiveFrom AS date), now(), now()) ' +
          'RETURNING salary_grade_table_id AS "salaryGradeTableId"',
        input,
      );
      return rows[0];
    });
  }

  @Put('/salary-grade-tables/:salaryGradeTableId')
  async updateSalaryGradeTable(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = req.params['salaryGradeTableId'];
    const data = checks.inputOf(req.body);
    const input = parseGrade(data);
    if (!/^\d+$/.test(id)) {
      throw invalid('호봉테이블 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE salary_grade_table_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SALARY_GRADE_NOT_FOUND', '호봉테이블 항목을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE grade_group = :gradeGroup AND step = CAST(:step AS integer) AND salary_grade_table_id <> CAST(:id AS bigint)',
        { gradeGroup: input.gradeGroup, step: input.step, id },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SALARY_GRADE_DUPLICATED', '수정 결과가 기존 호봉과 중복됩니다.');
      }
      const rows = await db.query(
        'UPDATE salary_grade_table SET grade_group = :gradeGroup, step = CAST(:step AS integer), amount = CAST(:amount AS numeric), ' +
          'effective_from = CAST(:effectiveFrom AS date), updated_at = now() ' +
          'WHERE salary_grade_table_id = CAST(:id AS bigint) ' +
          'RETURNING salary_grade_table_id AS "salaryGradeTableId"',
        { ...input, id },
      );
      return rows[0];
    });
  }

  @Get('/salary-grade-tables')
  async listSalaryGradeTables(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const pageNum = query['page'] === undefined || query['page'] === '' ? 0 : numberOf(query['page'], 'page');
    const sizeNum = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : numberOf(query['size'], 'size');
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw invalid('page, size 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeNum, MAX_SIZE);
    const gradeGroup = typeof query['gradeGroup'] === 'string' && query['gradeGroup'] !== '' ? query['gradeGroup'] : null;
    return transaction(async (db) => {
      const params = { gradeGroup, limit: size, offset: pageNum * size };
      const totals = await db.query(
        'SELECT COUNT(*) AS "total" FROM salary_grade_table WHERE (CAST(:gradeGroup AS varchar) IS NULL OR grade_group = CAST(:gradeGroup AS varchar))',
        { gradeGroup },
      );
      const items = await db.query(
        'SELECT salary_grade_table_id AS "salaryGradeTableId", grade_group AS "gradeGroup", step AS "step", amount AS "amount", effective_from AS "effectiveFrom" ' +
          'FROM salary_grade_table WHERE (CAST(:gradeGroup AS varchar) IS NULL OR grade_group = CAST(:gradeGroup AS varchar)) ' +
          'ORDER BY grade_group, step LIMIT :limit OFFSET :offset',
        params,
      );
      return { items, page: pageNum, size, total: Number(totals[0]['total']) };
    });
  }

  @Patch('/employee-salaries/:employeeSalaryId/grade')
  async assignEmployeeSalaryGrade(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const employeeSalaryId = req.params['employeeSalaryId'];
    const data = checks.inputOf(req.body);
    const gradeId = numberOf(data['salaryGradeTableId'], '호봉테이블 ID');
    if (!Number.isInteger(gradeId) || gradeId <= 0 || !/^\d+$/.test(employeeSalaryId)) {
      throw invalid('ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const salary = await db.query(
        'SELECT employee_salary_id FROM employee_salary WHERE employee_salary_id = CAST(:employeeSalaryId AS bigint)',
        { employeeSalaryId },
      );
      if (salary.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_SALARY_NOT_FOUND', '임직원 책정임금 정보를 찾을 수 없습니다.');
      }
      const grade = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE salary_grade_table_id = CAST(:gradeId AS bigint)',
        { gradeId },
      );
      if (grade.length === 0) {
        throw new ApiError(404, 'SALARY_GRADE_NOT_FOUND', '지정한 호봉을 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE employee_salary SET salary_grade_table_id = CAST(:gradeId AS bigint), updated_at = now() ' +
          'WHERE employee_salary_id = CAST(:employeeSalaryId AS bigint) ' +
          'RETURNING employee_salary_id AS "employeeSalaryId", salary_grade_table_id AS "salaryGradeTableId"',
        { gradeId, employeeSalaryId },
      );
      return rows[0];
    });
  }
}

