import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 10;

export default function FnSfr02107Page({ role, notify }: PageProps) {
  const [gradeGroupInput, setGradeGroupInput] = useState('');
  const [gradeGroup, setGradeGroup] = useState('');
  const [page, setPage] = useState(0);
  const [salaryPage, setSalaryPage] = useState(0);
  const [editing, setEditing] = useState<Row | 'new' | null>(null);
  const [assigning, setAssigning] = useState<Row | null>(null);

  const grades = useData<Page>(
    () => call<Page>('GET', '/salary-grade-tables', role, undefined, { gradeGroup, page, size: SIZE }),
    [gradeGroup, page],
  );
  const salaries = useData<Page>(
    () => call<Page>('GET', '/employee-salaries', role, undefined, { page: salaryPage, size: SIZE }),
    [salaryPage],
  );

  function search() {
    setPage(0);
    setGradeGroup(gradeGroupInput);
  }

  function reset() {
    setGradeGroupInput('');
    setGradeGroup('');
    setPage(0);
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles
          items={[
            ['호봉테이블 항목', <Num value={grades.data?.total ?? 0} />],
            ['책정임금 내역', <Num value={salaries.data?.total ?? 0} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>호봉테이블</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="직급/직군">
            <TextInput value={gradeGroupInput} onChange={setGradeGroupInput} />
          </Field>
        </Filters>
        <Band total={grades.data?.total}>
          <button type="button" onClick={() => setEditing('new')}>호봉 등록</button>
        </Band>
        {grades.error ? <ErrorText text={grades.error} /> : null}
        <DataTable
          rows={grades.data?.items ?? []}
          onRowClick={(row) => setEditing(row)}
          empty="등록된 호봉이 없습니다."
          columns={[
            { key: 'gradeGroup', label: '직급/직군' },
            { key: 'step', label: '호봉' },
            { key: 'amount', label: '호봉별 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'effectiveFrom', label: '적용 시작일', render: (r) => <DateText value={r['effectiveFrom']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={grades.data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>임직원 호봉</h2>
        {salaries.error ? <ErrorText text={salaries.error} /> : null}
        <DataTable
          rows={salaries.data?.items ?? []}
          empty="책정임금 내역이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'assignedSalary', label: '책정임금', render: (r) => <Num value={r['assignedSalary']} /> },
            { key: 'appliedFrom', label: '적용 시작일', render: (r) => <DateText value={r['appliedFrom']} /> },
            {
              key: 'grade',
              label: '호봉',
              render: (r) => (
                <button type="button" onClick={() => setAssigning(r)}>호봉 지정</button>
              ),
            },
          ]}
        />
        <Pager page={salaryPage} size={SIZE} total={salaries.data?.total ?? 0} onPage={setSalaryPage} />
      </section>

      {editing ? (
        <GradeDrawer
          row={editing === 'new' ? null : editing}
          role={role}
          onClose={() => setEditing(null)}
          onDone={(text) => {
            setEditing(null);
            notify(text);
            grades.reload();
          }}
        />
      ) : null}

      {assigning ? (
        <AssignDrawer
          row={assigning}
          role={role}
          onClose={() => setAssigning(null)}
          onDone={() => {
            setAssigning(null);
            notify('호봉을 지정했습니다.');
            salaries.reload();
          }}
        />
      ) : null}
    </div>
  );
}

function GradeDrawer({ row, role, onClose, onDone }: {
  row: Row | null;
  role: string;
  onClose: () => void;
  onDone: (text: string) => void;
}) {
  const [gradeGroup, setGradeGroup] = useState<string>(row ? String(row['gradeGroup'] ?? '') : '');
  const [step, setStep] = useState<number | string>(row ? (row['step'] as number) : '');
  const [amount, setAmount] = useState<number | string>(row ? (row['amount'] as number) : '');
  const [effectiveFrom, setEffectiveFrom] = useState<string>(row && row['effectiveFrom'] ? String(row['effectiveFrom']).slice(0, 10) : '');

  async function submit() {
    if (gradeGroup.trim() === '') {
      throw new Error('직급/직군을 입력하세요.');
    }
    if (step === '' || amount === '') {
      throw new Error('호봉과 호봉별 금액을 입력하세요.');
    }
    const body: Row = { gradeGroup, step, amount };
    if (effectiveFrom !== '') {
      body['effectiveFrom'] = effectiveFrom;
    }
    if (row) {
      await call('PUT', `/salary-grade-tables/${row['salaryGradeTableId']}`, role, body);
      onDone('호봉을 수정했습니다.');
    } else {
      await call('POST', '/salary-grade-tables', role, body);
      onDone('호봉을 등록했습니다.');
    }
  }

  return (
    <Drawer title={row ? '호봉 수정' : '호봉 등록'} onClose={onClose}>
      <Form onSubmit={submit} submit={row ? '수정' : '등록'}>
        <Field label="직급/직군" required>
          <TextInput value={gradeGroup} onChange={setGradeGroup} />
        </Field>
        <Field label="호봉" required>
          <NumberInput value={step} onChange={setStep} />
        </Field>
        <Field label="호봉별 금액" required>
          <NumberInput value={amount} onChange={setAmount} />
        </Field>
        <Field label="적용 시작일">
          <DateInput value={effectiveFrom} onChange={setEffectiveFrom} />
        </Field>
      </Form>
    </Drawer>
  );
}

function AssignDrawer({ row, role, onClose, onDone }: {
  row: Row;
  role: string;
  onClose: () => void;
  onDone: () => void;
}) {
  const [gradeId, setGradeId] = useState<number | string>(row['salaryGradeTableId'] ? (row['salaryGradeTableId'] as number) : '');

  async function submit() {
    if (gradeId === '') {
      throw new Error('호봉을 선택하세요.');
    }
    await call('PATCH', `/employee-salaries/${row['employeeSalaryId']}/grade`, role, { salaryGradeTableId: gradeId });
    onDone();
  }

  return (
    <Drawer title="임직원 호봉 지정" onClose={onClose}>
      <Form onSubmit={submit} submit="지정">
        <Field label="임직원">
          <RefName table="employee" role={role} value={row['employeeId']} />
        </Field>
        <Field label="호봉테이블 ID" required>
          <LookupSelect table="salary_grade_table" role={role} value={gradeId} onChange={setGradeId} />
        </Field>
      </Form>
    </Drawer>
  );
}
